for (int i = 3; i >= 1; i--)
{
    for (int j = 1; j <= i; j++)
        Console.Write("*");
    Console.WriteLine();
}

int sum = 0;
for (int i = 1; i <= 3; i++)
{
    int m = int.Parse(Console.ReadLine()) + 4;
    if (m > 100)
        m = 100;
    sum += m;
}
Console.WriteLine(sum / 3);

int count = 0;
for (int i = 1; i <= 12; i++)
    if (12 % i == 0)
        count++;
Console.WriteLine(count);
